@Bean
Step listadoBorrados(JobRepository repo, PlatformTransactionManager tx,
                     FlatFileItemReader<RegistroBorrado> borrados,
                     JasperItemWriter<RegistroBorrado> listadoR10) {
    return new StepBuilder("listadoBorrados", repo)
            .<RegistroBorrado, RegistroBorrado>chunk(500, tx)
            .reader(borrados)                                   // I05-BORRADOS
            .processor(r -> r.tipoReg() == 2 ? r : null)        // solo detalle; header y trailer se ignoran
            .writer(listadoR10)                                 // R10-BORRADOS
            .build();
}

